  function makeRamp() {
    var E = 9;          // flat entry slab length (m)
    var W = 6.0, T = 0.4;
    var LIP = 115 * Math.PI / 180;
    // curvature: bottom arc (R~10.5 m) blended in and out with C2 ramps, a near-straight
    // vertical run, then a hook whose curvature grows smoothly up to the lip.
    var k1 = 1 / 8.5, r1 = 4.5, L1 = 10, f1 = 5;
    var kUp0 = 0.02, kUp1 = 0.05, upLen = 16;
    function kappa(u) {
      if (u < 0) return 0;
      var e1 = r1 + L1;
      var k = k1 * (smooth5(u / r1) - smooth5((u - e1) / f1));
      var up = kUp0 + (kUp1 - kUp0) * smooth5((u - e1 - f1) / upLen);
      k += up * smooth5((u - e1) / f1);
      return k;
    }
    var ds = 0.01, s = 0, x = -E, y = 0, th = 0;
    var step = 0.05, S = [], X = [], Y = [], TH = [], K = [];
    var next = 0;
    while (true) {
      if (s >= next - 1e-9) { S.push(s); X.push(x); Y.push(y); TH.push(th); K.push(kappa(s - E)); next += step; }
      if (th >= LIP) break;
      var km = kappa(s - E + ds * 0.5);

