    var LIP = 165 * Math.PI / 180;
    // One continuous curve, curvature blended with C2 smoothsteps everywhere:
    // bottom bend -> long gently-curving lean-back -> tighter top bend -> near-horizontal
    // ceiling platform (pitch ~160-165 deg) where the car hangs upside down.
    var P = RAMP_P;
    function kappa(u) {
      if (u < 0) return 0;
      var e1 = P.r1 + P.L1, s3 = e1 + P.f1 + P.Lm, e3 = s3 + P.r3 + P.L3;
      var k = P.k1 * (smooth5(u / P.r1) - smooth5((u - e1) / P.f1));
      k += P.km * smooth5((u - e1) / P.f1);
      k += (P.k3 - P.km) * (smooth5((u - s3) / P.r3) - smooth5((u - e3) / P.f3));
      k += (P.kp - P.km) * smooth5((u - e3) / P.f3);
      return k;
    }
'''
