  const p={k1:1/R([14,15,16,17,18]),r1:R([5,6,7]),L1:R([10,12,14,16,18]),f1:R([5,6,7]),km:R([0.012,0.016,0.02,0.025,0.03]),Lm:R([6,8,10,12,14,16,18]),k3:1/R([9.5,10,11,12]),r3:R([3,4,5]),L3:R([2,4,6,8]),f3:R([3,4,5]),kp:R([0.008,0.012,0.016,0.02])};
  S.setRampParams(p); let r; try{ r=S.makeRamp(); }catch(e){continue}
  if(r.L>200) continue;
  const minR=1/Math.max(...r.K); if(minR<9.4) continue;
  // platform length with theta >= 150deg
  let plat=0; for(let j=0;j<r.n;j++) if(r.TH[j]>=150*Math.PI/180) plat+=0.05;
