python3 - <<'EOF'
s=open('render.js').read()
a=s.index("// ---- steel truss: towers, bracing, cross members (instanced beams)")
b=s.index("{\n  const geo = new THREE.BoxGeometry(1, 1, 1);")
new='''// ---- steel truss: tall tower, bracing, cross members, and a deck truss over the overhang (instanced beams)
const beams = [];
function beam(a, b, r = 0.12) { beams.push([a, b, r]); }
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);
{
  const xa = RAMP.xMax + TH + 1.1, xb = xa + 4.6, zc = W / 2 - 0.3;
  const top = RAMP.lipY + TH + 3.2;           // level of the frame above the ceiling platform
  const backAt = (s) => { const p = rampAt(s), nx = -Math.sin(p.th), ny = Math.cos(p.th); return { x: p.x - nx * TH, y: p.y - ny * TH, th: p.th }; };
  // tower: four main columns, rings every 3 m, X bracing on every face
  const levels = []; for (let y = 0; y < top - 0.5; y += 3) levels.push(y); levels.push(top);
  for (const [x, z] of [[xa, -zc], [xa, zc], [xb, -zc], [xb, zc]]) beam(V3(x, 0, z), V3(x, top, z), 0.24);
  for (const z of [-zc, zc]) beam(V3((xa + xb) / 2, 0, z), V3((xa + xb) / 2, top, z), 0.12);
  levels.forEach((y, i) => {
    beam(V3(xa, y, -zc), V3(xa, y, zc)); beam(V3(xb, y, -zc), V3(xb, y, zc));
    beam(V3(xa, y, -zc), V3(xb, y, -zc)); beam(V3(xa, y, zc), V3(xb, y, zc));
    if (i > 0) {
      const y0 = levels[i - 1];
      for (const z of [-zc, zc]) { beam(V3(xa, y0, z), V3(xb, y, z), 0.08); beam(V3(xb, y0, z), V3(xa, y, z), 0.08); }
      for (const x of [xa, xb]) { beam(V3(x, y0, -zc), V3(x, y, zc), 0.08); beam(V3(x, y0, zc), V3(x, y, -zc), 0.08); }
    }
  });
  // supports along the running surface
  let prevTop = null;
  for (let s = RAMP.E + 3; s <= RAMP.L + 0.01; s += 2.4) {
    const ss = Math.min(s, RAMP.L - 0.2), b = backAt(ss);
    if (b.y < 0.35) continue;
    for (const z of [-zc, zc]) {
      if (b.th < 1.0) beam(V3(b.x, b.y, z), V3(b.x, 0, z), 0.11);                 // posts under the bottom bend
      else if (b.x < xa - 0.3 && b.th < 2.2) beam(V3(b.x, b.y, z), V3(xa, b.y, z), 0.11); // ties to the tower
      if (b.th > 1.75 && b.y < top - 0.3) {                                        // hangers from the deck truss
        beam(V3(b.x, b.y, z), V3(b.x, top, z), 0.11);
        if (prevTop) beam(V3(b.x, b.y, z), V3(prevTop, top, z), 0.07);
      }
    }
    beam(V3(b.x, b.y, -zc), V3(b.x, b.y, zc), 0.09);                               // transverse stiffener
    if (b.th > 1.75) { beam(V3(b.x, top, -zc), V3(b.x, top, zc), 0.1); prevTop = b.x; }
  }
  // deck truss chords over the overhang, from above the lip back to the tower
  const lb = backAt(RAMP.L);
  for (const z of [-zc, zc]) {
    beam(V3(lb.x, top, z), V3(xb, top, z), 0.2);
    beam(V3(lb.x, lb.y, z), V3(lb.x, top, z), 0.12);
    beam(V3(lb.x, top, z), V3(xa, top - 6, z), 0.1);                                // raking strut into the tower
  }
  beam(V3(lb.x, top, -zc), V3(lb.x, top, zc), 0.12);
  // ground sills
